<?php
declare(strict_types=1);
require_once __DIR__.'/../../configuracion/inicializacion.php';
require_once __DIR__.'/../../servicios/casos_sunat/AccesoCasosSol.php';
asesconExigirPermiso($conexion,'BUZON_SOL','ver');$moduloActivo='CASOS_SOL';$actor=asesconUsuarioActual($conexion);$principal=asesconEsPrincipal($conexion);$csrf=asesconCsrf('csrf_buzon_sol');$casos=[];$errorCasos='';
try{$repo=AccesoCasosSol::repositorio();$casos=$repo?$repo->misCasos((int)$actor['id_usuario'],$principal):[];}catch(Throwable $e){$errorCasos='No se pudo conectar con la base principal.';}
$esc=static fn($v):string=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Mis casos SUNAT - ASESCON</title><link rel="stylesheet" href="<?=$esc(asesconUrl('publico/css/base/estructura_panel.css'))?>"><link rel="stylesheet" href="<?=$esc(asesconUrl('publico/css/modulos/sunat.css'))?>"></head><body><div class="app"><?php require __DIR__.'/../componentes/menu_lateral.php'; ?><main class="main-content"><?php require __DIR__.'/../componentes/barra_superior.php'; ?><section class="content"><div class="page-header"><div><h1>Mis casos SUNAT</h1><p>Asignaciones, casos compartidos, prioridades y fechas límite.</p></div></div>
<?php if($errorCasos):?><p class="notice bad" role="alert"><?=$esc($errorCasos)?></p><?php endif;?>
<div class="reference-panel"><div class="table-container"><table><thead><tr><th>Cliente</th><th>Caso</th><th>Responsable</th><th>Prioridad</th><th>Fecha límite</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
<?php if(!$casos):?><tr><td colspan="7">No tienes casos asignados o compartidos.</td></tr><?php endif;?>
<?php foreach($casos as $c):?><tr data-caso="<?=(int)$c['id_documento']?>"><td><?=$esc($c['cliente'])?><small><?=$esc($c['ruc'])?></small></td><td><?=$esc($c['asunto'])?></td><td><?=$esc($c['responsable'])?></td><td><?=$esc($c['prioridad'])?></td><td><?=$esc($c['fecha_limite']?:'Sin fecha')?><?php if($c['estado']!=='CERRADO'&&!empty($c['fecha_limite'])&&$c['fecha_limite']<date('Y-m-d')):?><strong> Vencido</strong><?php endif;?></td><td data-estado-caso><?=$esc($c['estado'])?></td><td><div class="reference-actions"><?php foreach(['pdf'=>'PDF','notas'=>'Notas','correo'=>'Correo','whatsapp'=>'WhatsApp'] as $accion=>$etiqueta):?><button type="button" class="mini-btn" data-accion-buzon="<?=$accion?>" data-id-documento="<?=(int)$c['id_documento']?>"><?=$etiqueta?></button><?php endforeach;?><?php if($principal):?><button type="button" class="mini-btn" data-accion-buzon="asignacion" data-id-documento="<?=(int)$c['id_documento']?>">Asignación</button><?php endif;?></div>
<?php if(($principal||(int)$c['id_responsable']===(int)$actor['id_usuario'])&&asesconTienePermiso($conexion,'BUZON_SOL','editar')):?><form data-form-estado-caso action="<?=$esc(asesconUrl('api/buzones/estado_caso_sol.php'))?>" method="post"><input type="hidden" name="csrf_token" value="<?=$esc($csrf)?>"><input type="hidden" name="id_documento" value="<?=(int)$c['id_documento']?>"><input type="hidden" name="estado" value="<?=$c['estado']==='CERRADO'?'ABIERTO':'CERRADO'?>"><button class="mini-btn"><?=$c['estado']==='CERRADO'?'Reabrir caso':'Marcar resuelto'?></button><span role="status"></span></form><?php endif;?></td></tr><?php endforeach;?>
</tbody></table></div></div><?php require __DIR__.'/ventanas/acciones_sol.php'; ?></section></main></div>
<script src="<?=$esc(asesconUrl('publico/js/navegacion/menu_lateral.js'))?>"></script><script src="<?=$esc(asesconUrl('publico/js/navegacion/menu_movil.js'))?>"></script><script src="<?=$esc(asesconUrl('publico/js/navegacion/busqueda_clientes.js'))?>"></script><script defer src="<?=$esc(asesconUrl('publico/js/buzones/estado_caso.js'))?>"></script>
<script>document.addEventListener('DOMContentLoaded',()=>{const id=Number(new URL(location.href).searchParams.get('caso'));if(id>0){const fila=document.querySelector('[data-caso="'+id+'"]');if(fila){fila.scrollIntoView({behavior:'smooth',block:'center'});fila.style.outline='3px solid #c9a24a';fila.style.outlineOffset='-3px';fila.style.transition='outline-color .3s ease';window.setTimeout(()=>{fila.style.outline='';fila.style.outlineOffset='';},5000);}}});</script></body></html>
